function saveSession(s){if(s&&!s.expires_at)s.expires_at=Math.floor(Date.now()/1000)+(s.expires_in||3600);state.session=s;if(s)localStorage.setItem('family-session',JSON.stringify(s));else localStorage.removeItem('family-session')}
