function errorText(e){const s=e.message||'تعذّر تنفيذ الطلب. حاول مجددًا.';if(/Invalid login credentials/i.test(s))return 'البريد أو كلمة المرور غير صحيحة.';if(/Email not confirmed/i.test(s))return 'أكد بريدك أولًا من رسالة التأكيد.';if(/rate limit/i.test(s))return 'وصلت إلى الحد المؤقت للطلبات. انتظر قليلًا ثم حاول مجددًا.';if(/Failed to fetch|NetworkError/i.test(s))return 'تعذّر الاتصال. تحقق من الإنترنت ثم حاول مجددًا.';if(/row-level security|permission denied/i.test(s))return 'صلاحيات حسابك لا تسمح بهذا الإجراء. حدّث حالة الحساب.';return s}
async function req(path,{method='GET',body,auth=true,raw=false,headers={}}={}){
 if(auth&&state.session&&state.session.expires_at*1000<Date.now()+60000){const s=await req('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:state.session.refresh_token},auth:false});saveSession(s)}
 const h={apikey:KEY,...headers};if(auth&&state.session)h.Authorization='Bearer '+state.session.access_token;
 if(body&&!raw)h['Content-Type']='application/json';
 const res=await fetch(ORIGIN+path,{method,headers:h,body:body?(raw?body:JSON.stringify(body)):undefined,cache:'no-store'});
 const data=res.status===204?null:await res.json().catch(()=>null);
 if(!res.ok){if(res.status===401&&auth){saveSession(null);state.user=null;$('app-screen').hidden=true;$('auth-screen').hidden=false}throw new Error(data?.msg||data?.message||data?.error_description||data?.error||'تعذّر تنفيذ الطلب ('+res.status+')')}
 return data;
}
