async function start(){if(!state.session)return;const user=await req('/auth/v1/user');state.user=user;const profiles=await table('profiles','select=id,display_name,role,status,is_root,avatar_path&id=eq.'+encodeURIComponent(user.id));if(!profiles?.[0])throw new Error('لم يكتمل إعداد الحساب. تواصل مع مدير التطبيق.');state.profile=profiles[0];await community.load();const p=state.profile;$('auth-screen').hidden=true;$('app-screen').hidden=false;$('header-actions').hidden=false;document.querySelector('.private-badge').hidden=true;$('user-name').textContent=p.display_name;$('user-role').textContent=p.is_root?'المدير الرئيسي':({admin:'مدير',journalist:'صحفي',member:'عضو'}[p.role]);const active=p.status==='active';$('pending').hidden=active;$('approved').hidden=!active;$('pending-text').textContent=p.status==='suspended'?'حسابك موقوف مؤقتًا. راجع مدير العائلة.':'أكدت بريدك بنجاح. سيعتمد المدير حسابك قبل إتاحة أخبار العائلة.';if(!active)return;$('drafts-toggle').hidden=!['admin','journalist'].includes(p.role);$('new-post').hidden=!['admin','journalist'].includes(p.role);$('members-tab').hidden=p.role!=='admin';$('trash-tab').hidden=p.role!=='admin';$('announcements-tab').hidden=p.role!=='admin';await loadActiveAnnouncements();await showSection('news')}
