async function renderPost(p){const card=element('article',undefined,'card post');const head=element('div',undefined,'post-head');const name=p.profiles?.display_name||'فرد من العائلة';const by=element('div',name);by.append(element('small',new Date(p.created_at).toLocaleString('ar-SA')));const avatar=element('span',name.slice(0,1),'avatar');if(p.profiles?.avatar_path){req('/storage/v1/object/sign/profile-images/'+p.profiles.avatar_path,{method:'POST',body:{expiresIn:600}}).then(r=>{const img=element('img');img.src=ORIGIN+'/storage/v1'+r.signedURL;img.alt=name;avatar.replaceChildren(img)}).catch(()=>{});}head.append(avatar,by);card.id='post-'+p.id;card.append(head,element('h2',p.title),element('p',p.body,'body'));if(!p.published)card.append(element('small',({pending:'بانتظار موافقة المدير',rejected:'رُفض النشر — يمكنك التعديل والإرسال مجددًا',draft:'مسودة'}[p.moderation_status]||'مسودة')));if(p.image_path){try{const img=element('img',undefined,'post-image');img.alt=p.title;img.loading='lazy';img.src=await signedImage(p.image_path);img.onerror=()=>{img.replaceWith(button('↻ إعادة تحميل الصورة',async()=>{img.src=await signedImage(p.image_path);card.insertBefore(img,actions)}))};card.append(img)}catch{card.append(element('p','تعذّر تحميل الصورة. حدّث الأخبار للمحاولة مجددًا.','muted'))}}
 const actions=element('div',undefined,'post-actions');const mine=await table('likes','select=user_id&post_id=eq.'+p.id+'&user_id=eq.'+state.user.id);let liked=!!mine.length,count=p.likes?.[0]?.count||0;
 const like=button('',async()=>{await table('likes','post_id=eq.'+p.id+'&user_id=eq.'+state.user.id,{method:liked?'DELETE':'POST',body:liked?undefined:{post_id:p.id,user_id:state.user.id}});count+=liked?-1:1;liked=!liked;paintLike()});function paintLike(){like.textContent=(liked?'♥':'♡')+' '+count+' إعجاب';like.classList.toggle('liked',liked)}paintLike();actions.append(like);let opened=false;const cs=element('div',undefined,'comments');cs.hidden=true;const cb=button('◌ التعليقات · '+(p.comments?.[0]?.count||0),async()=>{opened=!opened;cs.hidden=!opened;if(opened)await loadComments(p,cs)});actions.append(cb);if(state.profile.role==='admin'||p.author_id===state.user.id&&state.profile.role==='journalist'){actions.append(button('✎ تعديل',()=>openEditor(p)),button('إخفاء',async()=>{if(!confirm('إخفاء هذا الخبر؟ يمكن للمدير استعادته.'))return;await table('posts','id=eq.'+p.id,{method:'PATCH',body:{deleted_at:new Date().toISOString()}});await feed(true)},'text-button danger'))}if(state.profile.role==='admin')actions.insertBefore(button('حذف',()=>deletePost(p),'text-button danger'),actions.lastElementChild);card.append(actions,cs);$('feed').append(card)}
async function loadComments(p,box,offset=0){if(!offset)box.replaceChildren();const rows=await table('comments','select=id,body,author_id,created_at,profiles:profiles!comments_author_id_fkey(display_name)&post_id=eq.'+p.id+'&order=created_at.asc,id.asc&limit=50&offset='+offset);for(const c of rows){const d=element('div',undefined,'comment');d.append(element('small',(c.profiles?.display_name||'عضو')+' · '+new Date(c.created_at).toLocaleDateString('ar-SA')),element('span',c.body));if(c.author_id===state.user.id||state.profile.role==='admin')d.append(button('حذف التعليق',async()=>{if(!confirm('حذف التعليق نهائيًا؟'))return;await table('comments','id=eq.'+c.id,{method:'DELETE'});await loadComments(p,box)}));box.append(d)}if(rows.length===50)box.append(button('عرض تعليقات أخرى',async()=>{await loadComments(p,box,offset+50)}));if(!offset){const form=element('form',undefined,'comment-form');const input=element('input');input.placeholder='اكتب كلمة لطيفة…';input.required=true;input.maxLength=2000;input.setAttribute('aria-label','تعليق جديد');const send=element('button','إرسال','primary');form.append(input,send);form.onsubmit=async e=>{e.preventDefault();await busy(send,async()=>{const body=input.value.trim();if(!body)return;await table('comments','',{method:'POST',body:{post_id:p.id,author_id:state.user.id,body}});await loadComments(p,box)})};box.append(form)}}
function openEditor(p=null){closeMenu();mentions.open(p);state.edit=p;$('editor-title').textContent=p?'تعديل الخبر':'خبر جديد للعائلة';$('post-title').value=p?.title||'';$('post-body').value=p?.body||'';$('post-published').checked=p?.published??true;$('post-image').value='';$('post-image').disabled=!!p&&p.author_id!==state.user.id;$('post-message').textContent=$('post-image').disabled?'صورة الخبر يغيرها الصحفي الذي رفعها.':'';$('editor').showModal()}
