async function compress(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('اختر صورة JPEG أو PNG أو WebP.');if(file.size>20*1024*1024)throw new Error('الصورة الأصلية تتجاوز 20 ميجابايت.');const url=URL.createObjectURL(file);try{const img=new Image;img.src=url;await img.decode();const canvas=document.createElement('canvas');let scale=1;for(let i=0;i<7;i++){canvas.width=Math.round(1080*scale);canvas.height=Math.round(1350*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);const fit=Math.min(canvas.width/img.width,canvas.height/img.height);ctx.drawImage(img,(canvas.width-img.width*fit)/2,(canvas.height-img.height*fit)/2,img.width*fit,img.height*fit);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',Math.max(.45,.8-i*.05)));if(blob&&blob.size<=409600)return blob;scale*=.8}throw new Error('تعذّر ضغط الصورة إلى الحجم المسموح. اختر صورة أخرى.')}finally{URL.revokeObjectURL(url)}}
$('post-form').onsubmit=async e=>{e.preventDefault();await busy($('save-post'),async()=>{const title=$('post-title').value.trim(),body=$('post-body').value.trim();if(title.length<3||!body)throw new Error('أدخل عنوانًا من 3 أحرف على الأقل ونص الخبر.');let path=state.edit?.image_path||null,uploaded=null;const file=$('post-image').files[0];if(file){$('post-message').textContent='جاري ضغط الصورة وحفظها…';const blob=await compress(file);uploaded=state.user.id+'/'+crypto.randomUUID()+'.jpg';await req('/storage/v1/object/news-images/'+uploaded,{method:'POST',body:blob,raw:true,headers:{'Content-Type':'image/jpeg'}});path=uploaded}try{const values={mentioned_member_ids:mentions.ids(),title,body,image_path:path,published:$('post-published').checked};if(state.edit)await table('posts','id=eq.'+state.edit.id,{method:'PATCH',body:values});else await table('posts','',{method:'POST',body:{...values,author_id:state.user.id}})}catch(err){if(uploaded)try{await req('/storage/v1/object/news-images',{method:'DELETE',body:{prefixes:[uploaded]}})}catch{}throw err}$('editor').close();toast(state.profile.role==='journalist'&&state.settings?.journalist_approval&&$('post-published').checked?'تم إرسال الخبر لموافقة المدير.':'تم حفظ الخبر بنجاح.');await feed(true)})};
