function renderMembers(){const box=$('members-list');box.replaceChildren();for(const p of state.members.filter(p=>p.display_name.includes($('member-search').value.trim()))){const row=element('div',undefined,'member');const label=element('span',p.display_name);label.append(element('small',p.is_root?'مدير رئيسي محمي':p.id===state.user.id?'حسابك':p.status==='pending'?'طلب انضمام جديد':'عضو بالعائلة'));row.append(label);const role=element('select'),status=element('select');role.setAttribute('aria-label','دور '+p.display_name);status.setAttribute('aria-label','حالة '+p.display_name);for(const [v,t]of[['member','عضو'],['journalist','صحفي'],['admin','مدير']]){const opt=element('option',t);opt.value=v;role.append(opt)}for(const[v,t]of[['pending','قيد المراجعة'],['active','معتمد'],['suspended','موقوف']]){const opt=element('option',t);opt.value=v;status.append(opt)}role.value=p.role;status.value=p.status;const save=button('حفظ',async()=>{await table('profiles','id=eq.'+p.id,{method:'PATCH',body:{role:role.value,status:status.value}});toast('تم تحديث العضو.');await members()},'secondary');if(p.is_root||p.id===state.user.id)role.disabled=status.disabled=save.disabled=true;row.append(role,status,save,button('بيانات التسجيل',async()=>{const d=await community.memberDetail(p.id);const dialog=element('dialog');dialog.append(element('h2',p.display_name),element('p','الاسم الرباعي: '+(d.full_name||'غير مكتمل')),element('p','البريد: '+d.email+(d.email_confirmed?' (مؤكد)':' (غير مؤكد)')),element('p','الجوال: '+(d.phone||'غير مكتمل')),element('p','الجنس: '+({male:'ذكر',female:'أنثى'}[d.gender]||'غير محدد')),element('p','المعرّف: '+(d.reference_name||'—')+' / '+({father:'أب',husband:'زوج',brother:'أخ',uncle:'عم',maternal_uncle:'خال'}[d.relationship]||'—')),button('إغلاق',()=>{dialog.close();dialog.remove()}));document.body.append(dialog);dialog.showModal();}));box.append(row)}if(!box.children.length)box.append(element('p','لا توجد نتائج.','muted'))}
