  card.append(element('span',labels[status],'ad-status '+status),element('h3',ad.title),element('p',ad.body),element('small',new Date(ad.starts_at).toLocaleString('ar-SA')+' ← '+new Date(ad.ends_at).toLocaleString('ar-SA')));
